# Define the custom CUDA kernel for matrix multiplication with shared memory
mm_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Tile size for shared memory
#define TILE_DIM 32

__global__ void square_matrix_multiply_kernel_shm(const float* A, const float* B, float* C, int N) {
    // Block-local shared memory for tiles of A and B
    __shared__ float shA[TILE_DIM][TILE_DIM];
    __shared__ float shB[TILE_DIM][TILE_DIM];

    // Global row and column for the current thread
    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int col = blockIdx.x * TILE_DIM + threadIdx.x;

    float sum = 0.0f;

    // Iterate over tiles
    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tiles into shared memory
        if (row < N && t * TILE_DIM + threadIdx.x < N) {
            shA[threadIdx.y][threadIdx.x] = A[row * N + (t * TILE_DIM + threadIdx.x)];
        } else {
            shA[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if outside bounds
        }

        if (t * TILE_DIM + threadIdx.y < N && col < N) {
            shB[threadIdx.y][threadIdx.x] = B[(t * TILE_DIM + threadIdx.y) * N + col];
        } else {
            shB[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if outside bounds
        }
        __syncthreads();

        // Perform dot product using shared memory
        for (int i = 0; i < TILE_DIM; ++i) {
            sum += shA[threadIdx.y][i] * shB[i][threadIdx.x];
        }
        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
